def segmented_sieve(start, end):
    """Generate primes in [start, end]"""
    if end < 2:
        return []

    # Generate base primes up to sqrt(end)
    max_sqrt = int(end**0.5) + 1
    base_primes = []
    if max_sqrt >= 2:
        is_prime = [True] * (max_sqrt + 1)
        is_prime[0] = is_prime[1] = False
        for i in range(2, max_sqrt + 1):
            if is_prime[i]:
                base_primes.append(i)
                for j in range(i*i, max_sqrt + 1, i):
                    is_prime[j] = False

    # Sieve the segment
    segment_size = end - start + 1
    is_prime = [True] * segment_size

    for p in base_primes:
        first_multiple = max(p*p, ((start + p - 1) // p) * p)
        for j in range(first_multiple, end + 1, p):
            is_prime[j - start] = False

    return [start + i for i in range(segment_size) if is_prime[i]]
