from functools import lru_cache

def solution(s):
    """
    Hexagonal chocolate game solution.
    Karlsson moves first. Both players play optimally.
    Returns 'Karlsson' if he wins, 'Lillebror' otherwise.
    """
    lines = s.strip().split('\n')
    grid = [line.split() for line in lines]

    # Collect chocolate positions (row, col)
    positions = []
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if grid[r][c] == 'O':
                positions.append((r, c))

    if not positions:
        return "Lillebror\n"

    @lru_cache(maxsize=None)
    def can_force_win(state):
        """Returns True if current player can force a win from this state."""
        state_set = set(state)

        if not state_set:
            return False

        moves = set()

        # Horizontal moves (same row, consecutive columns)
        for r in range(len(grid)):
            cols = sorted([c for c in range(len(grid[r])) if (r, c) in state_set])
            if cols:
                for i in range(len(cols)):
                    line_cols = cols[i:i+5]
                    if len(line_cols) >= 1:
                        line = tuple(sorted([(r, c) for c in line_cols]))
                        # Only add move if all positions have chocolates
                        if all((r, c) in state_set for (r2, c) in line[:1]):
                            moves.add(line)

        # Try to find a winning move
        for move in sorted(moves, key=lambda m: len(m), reverse=True):
            new_state = state - move
            if not can_force_win(tuple(sorted(new_state))):
                return True

        return False

    if can_force_win(tuple(sorted(positions))):
        return "Karlsson\n"
    else:
        return "Lillebror\n"
