    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    target = math.ceil(math.sqrt(n))

    visited = [False] * (n + 1)
    depth = [0] * (n + 1)
    parent = [0] * (n + 1)

    cycle_found = False
    cycle_path = []

    def dfs(u, d, p):
        nonlocal cycle_found, cycle_path
        visited[u] = True
        depth[u] = d
        parent[u] = p

        for v in adj[u]:
            if not visited[v]:
                dfs(v, d + 1, u)
            elif v != p:
                cycle_len = d - depth[v] + 1
                if cycle_len >= target:
                    cycle_path = [v]
                    curr = u
                    while curr != v:
                        cycle_path.append(curr)
                        curr = parent[curr]
                    cycle_found = True
                    return

    dfs(1, 0, 0)

    if cycle_found:
        return f"2\n{len(cycle_path)}\n" + " ".join(map(str, cycle_path)) + "\n"

    indep_set = []
    for i in range(1, n + 1):
        if depth[i] < target:
            indep_set.append(i)

    while len(indep_set) < target:
        for i in range(1, n + 1):
            if depth[i] >= target and len([j for j in range(1, n+1) if depth[i] == depth[j]]) >= target - len(indep_set):
                indep_set.append(i)
                break
            if i == n:
                break

    if len(indep_set) >= target:
        indep_set = indep_set[:target]

    while len(indep_set) < target:
        for i in range(1, n + 1):
            if not (depth[i] >= target) or (i not in indep_set):
                indep_set.append(i)
                break
        if i == n:
            break

    return f"1\n{target}\n" + " ".join(map(str, indep_set)) + "\n"
