    n, k, m = map(int, input_str.strip().split())
    MOD = 10**9 + 7

    if k == 1:
        return str(n % MOD)

    # For small k and m, use DP
    # dp[i][mask] = number of ways to visit k planets ending at planet i
    # but we need to track which planets are visited

    # Since k is small (<= 12), we can use DP with bitmask for visited planets
    # But we need to consider which planets are valid positions

    # Alternative approach: DP where we track the current position and visited set
    # Since we only need to visit k planets, and m is small, we can optimize

    dp = {}  # (current_position, visited_mask) -> count

    def get_next_positions(x, visited):
        neighbors = []
        for y in range(1, min(n, x + m) + 1):
            if y not in visited:
                neighbors.append(y)
        return neighbors

    # Initialize for all possible starting planets
    for start in range(1, n + 1):
        visited = {start}
        dp[(start, frozenset(visited))] = 1

    # Count paths of length k
    from functools import lru_cache

    # Use DFS with memoization
    # cache(current_pos, k_remaining, visited_mask)

    @lru_cache(maxsize=None)
    def count_ways(pos, k_remaining, visited_tuple):
        if k_remaining == 0:
            return 1

        if k_remaining < 0:
            return 0

        count = 0
        visited_set = set(visited_tuple)

        # Find all valid next positions
        for next_pos in range(1, min(n, pos + m) + 1):
            if next_pos not in visited_set:
                new_visited = visited_tuple + (next_pos,)
                count = (count + count_ways(next_pos, k_remaining - 1, new_visited)) % MOD

        return count

    result = 0
    for start in range(1, n + 1):
        result = (result + count_ways(start, k - 1, (start,))) % MOD

    return str(result)
