    n2 = [p3[0] - p1[0], p3[1] - p1[1], p3[2] - p1[2]]
    cross = [n1[1] * n2[2] - n1[2] * n2[1], n1[2] * n2[0] - n1[0] * n2[2], n1[0] * n2[1] - n1[1] * n2[0]]
    mag = math.sqrt(sum(x**2 for x in cross))

    if mag < 1e-9:
        return sphere_from_2(p1, p2)

    mp = [(p1[i] + p2[i]) / 2.0 for i in range(3)]

    m = []
    for i in range(3):
        if i < 2:
            j = i + 1
            m.append([cross[i], -(cross[j] if j < 3 else 0)])

    system = []
    for i in range(3):
        row = [mp[0], mp[1], mp[2]]
        row.append(sum((p1[k] - p2[k])**2 / 4 for k in range(3)))
        system.append([row[0], row[1], row[2]] + row[3:4])

    center = gaussian_eliminate(system)

    if not center:
        return sphere_from_2(p1, p2)

    center = (center[0], center[1], center[2])
    radius = distance(p1, center)
