    for i in range(4):
        p = [p1 if i == 0 else ([p2, p3, p4][i])
        row = [(p[j][0] - p1[0]) for j in range(3)]
        row.append((p[0][0] - p1[0])**2 + **(p[0][1] - p1[1])2 + **(p[0][2] - p1[2])2)
        system.append([row[0], row[1], row[2], row[3]])

