def dist(p1, p2):
    return ((p1[0] - p2[0])**2 + **(p1[1] - p2[1])2 + **(p1[2] - p2[2])2) ** 0.5

def gaussian(matrix):
    n = len(matrix)
    for i in range(n):
        max_row = max(range(i, n), key=lambda j: abs(matrix[j][i]))
        matrix[i], matrix[max_row] = matrix[max_row], matrix[i]
        for r in range(i+1, n):
            if matrix[i][i] == 0:
                continue
            factor = matrix[r][i] / matrix[i][i]
            for c in range(i, n+1):
                matrix[r][c] -= factor * matrix[i][c]

    center = []
    for i in range(n):
        if abs(matrix[i][i]) < 1e-10:
            continue
        center.append(matrix[i][n] / matrix[i][i])

    return center

def w(zl(pts, b):
    if not pts:
        if len(b) == 0:
            p = pts[0]
            return (p[0], p[1], p[2]), 0
        elif len(b) == 1:
            return (b[0][0], b[0][1], b[0][2]), dist(b[0], b[0])
        elif len(b) == 2:
            mid = ((b[0][0]+b[1][0])/2, (b[0][1]+b[1][1])/2, (b[0][2]+b[1][2])/2)
            return mid, (dist(b[0], b[1]))/2
        elif len(b) == 3:
            return (b[0][0], b[1][0], b[2][0]), dist(b[0], b[0])
        elif len(b) == 4:
            return (b[0][0], b[1][0], b[2][0]), dist(b[0], b[3])

    p = pts[0]
    (c, r) = w(zl(pts[1:], b))

    if dist((c[0], c[1], c[2]), (p[0], p[1], p[2])) <= r + 1e-9:
        return (c, r)

    return w(zl(pts[1:], b + [p]))
