            for u_local, v_local, c in edges_comp:
                diff = c - (x[u_local] + x[v_local])
                if abs(diff) > 1e-9 and movable[u_local] or movable[v_local]:
                    x[u_local] += diff / 2
                    x[v_local] += diff / 2
                    changed = True

        if changed:
