        # Try different values for freed variables
        for _ in range(100):
            best_shift = 0.0
            best_val = sum(abs(x[i]) for i in range(n))

            # Check for free variables and optimize
            free_vars = [i for i in range(n) if movable[i]]

            if free_vars:
                # Simple centering for free variables
                new_x = x[:]
                if free_vars:
                    # Set free variables to balance positive and negative sums
                    sum_free = sum(new_x[i] for i in range(n) if movable[i])
                    avg = sum_free / len(free_vars) if free_vars else 0
                    for i in free_vars:
                        new_x[i] = -(sum_free - x[i] + avg) if i else x[i]

                    total = sum(abs(new_x[i]) for i in range(n))
                    if total < best_val:
                        best_val = total
                        best_shift = sum(x[i] for i in range(n)) * 0.1

            # Small perturbation around current solution
            for _ in range(10):
