                        break

                if valid and sum(abs(val) for val in test_x) < best_val:
                    best_val = sum(abs(val) for val in test_x)
                    for i in range(n):
                        x[i] = test_x[i]

        # Return shifted solution
        final_x = [x[i] for i in range(n)]

        # Scale to normalize
        scaling = sum(abs(x[i]) for i in range(n))
        if scaling > 1e-9:
            final_x = [xi / scaling for xi in final_x]
            # Then scale back
            scaling = 1.0

