from typing import List

MOD = 10**9 + 7
MAX = 2000005

# Precompute factorials
fact = [1] * MAX
inv = [1] * MAX

def precompute():
    for i in range(1, MAX):
        fact[i] = (fact[i-1] * i) % MOD

    inv[MAX-1] = pow(fact[MAX-1], MOD-2, MOD)
    for i in range(MAX-2, -1, -1):
        inv[i] = (inv[i+1] * (i+1)) % MOD

def nCr(n, r):
    if r < 0 or r > n:
        return 0
    return fact[n] * inv[r] % MOD * inv[n-r] % MOD

# min_prime_factor[i] stores the smallest prime factor of i
min_prime_factor = [0] * MAX

def sieve():
    for i in range(2, int(MAX**0.5) + 1):
        if min_prime_factor[i] == 0:
            for j in range(i*i, MAX, i):
                if min_prime_factor[j] == 0:
                    min_prime_factor[j] = i
    for i in range(2, MAX):
        if min_prime_factor[i] == 0:
            min_prime_factor[i] = i

def solve_for_n(r, n):
    if n == 1:
        return 1

    ans = 1
    temp = n

    while temp > 1:
        p = min_prime_factor[temp]
        exponent = 0
        while temp % p == 0:
            temp //= p
            exponent += 1

        # Each prime power p^exponent contributes C(r + exponent - 1, exponent) ways
        term = nCr(r + exponent - 1, exponent)
        if term != 0:
            ans = (ans * term) % MOD

    return ans

def solution(input_str: str) -> str:
    precompute()
    sieve()

    import sys
    from io import StringIO

    sys.stdin = StringIO(input_str)
    sys.stdin.readline()  # Skip q, we read lines directly

    output_lines = []
    for line in sys.stdin:
        r_str, n_str = line.strip().split()
        r = int(r_str)
        n = int(n_str)
        output_lines.append(str(solve_for_n(r, n)))

    sys.stdin = sys.__stdin__
    return '\n'.join(output_lines)
