    # 2-color the conflict graph (bipartite coloring)
    colors = [None] * m
    possible = True

    def dfs(u, c):
        colors[u] = c
        for v in build[u]:
            if colors[v] is None:
                if not dfs(v, 1 - c):
                    return False
            elif colors[v] == c:
                return False
        return True

    for i in range(m):
        if colors[i] is None:
            if not dfs(i, 0):
                possible = False
                break

    if not possible:
        return "Impossible\n"

    return ''.join('i' if colors[i] == 0 else 'o' for i in range(m)) + '\n'
