def is_bipartite(adj, comp):
    """Check if the subgraph induced by comp is bipartite."""
    comp_set = set(comp)
    colors = {}

    for start in comp:
        if start in colors:
            continue

        colors[start] = 0
        queue = [start]

        while queue:
            u = queue.pop(0)
            for v in adj[u]:
                if v not in comp_set:
                    continue
                if v not in colors:
                    colors[v] = 1 - colors[u]
                    queue.append(v)
                elif colors[v] == colors[u]:
                    return False

    return True


def count_independent_sets(comp, adj):
    """Count number of independent sets in the subgraph induced by comp."""
    size = len(comp)
    if size == 0:
        return 1
    if size == 1:
        return 2

    comp_set = set(comp)

    # Check if there are any edges within the component
    has_edges = False
    for u in comp:
        for v in adj[u]:
            if v in comp_set:
                has_edges = True
                break
        if has_edges:
            break

    if not has_edges:
        return 1 << size  # All subsets are independent

    # Build local adjacency list (only counting each edge once)
    idx_map = {u: i for i, u in enumerate(comp)}
    adj_local = [[] for _ in range(size)]
    for i in range(size):
        u = comp[i]
        for v in adj[u]:
            if v in comp_set and v != u:
                j = idx_map[v]
                if j > i:
                    adj_local[i].append(j)

    # For sizes up to 25, use direct enumeration
    if size <= 25:
        count = 0
        for mask in range(1 << size):
            is_indep = True
            for i in range(size):
                if mask & (1 << i):
                    for neighbor in adj_local[i]:
                        if mask & (1 << neighbor):
                            is_indep = False
                            break
                    if not is_indep:
                        break
            if is_indep:
                count += 1
        return count

    # For larger sizes, use dynamic programming with recursion
    memo = {}

    def cnt(idx, mask):
        if idx == size:
            return 1

        key = (idx, mask)
        if key in memo:
            return memo[key]

        # Option 1: Don't include vertex idx in the independent set
        c = cnt(idx + 1, mask)

        # Option 2: Include vertex idx (only if no neighbor is already in the set)
        can_include = True
        for neighbor in adj_local[idx]:
            if mask & (1 << neighbor):
                can_include = False
                break

        if can_include:
            c += cnt(idx + 1, mask | (1 << idx))

        memo[key] = c
        return c

    return cnt(0, 0)


def solution(input_data):
    """
    Count the number of ways to assign 0/1 to vertices such that:
    - At least one edge has sum 0 (both endpoints 0)
    - At least one edge has sum 1 (one endpoint 0, one endpoint 1)
    - At least one edge has sum 2 (both endpoints 1)

    Uses inclusion-exclusion principle.
    """
    lines = input_data.strip().split('\n')
    if not lines:
        return "0\n"

    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    # Find connected components
    visited = [False] * (n + 1)
    components = []
    for i in range(1, n + 1):
        if not visited[i]:
            comp = []
            stack = [i]
            visited[i] = True
            while stack:
                u = stack.pop()
                comp.append(u)
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        stack.append(v)
            components.append(comp)

    def has_edges_in_comp(comp):
        """Check if there are any edges within the component."""
        comp_set = set(comp)
        for u in comp:
            for v in adj[u]:
                if v in comp_set:
                    return True
        return False

    # Use inclusion-exclusion:
    # Total - |S0| - |S1| - |S2| + |S0∩S1| + |S0∩S2| + |S1∩S2| - |S0∩S1∩S2|
    # where:
    # S0 = assignments with NO edge of sum 0 (vertices labeled 0 form independent set)
    # S1 = assignments with NO edge of sum 1 (connected vertices must have same value)
    # S2 = assignments with NO edge of sum 2 (vertices labeled 1 form independent set)

    # |S0| and |S2|: product of independent set counts for each component
    s0 = s2 = 1
    for comp in components:
        s0 *= count_independent_sets(comp, adj)
        s2 *= count_independent_sets(comp, adj)

    # |S1|: 2 choices per component (all 0 or all 1)
    s1 = 2 ** len(components)

    # |S0 ∩ S1|: No (0,0) and no (0,1) => edges must be (1,1) or not exist
    # => Components with edges must have all vertices = 1
    c01 = 1
    for comp in components:
        c01 *= (1 if has_edges_in_comp(comp) else 2)

    # |S2 ∩ S1|: No (1,1) and no (0,1) => edges must be (0,0) or not exist
    # => Components with edges must have all vertices = 0
    c21 = 1
    for comp in components:
        c21 *= (1 if has_edges_in_comp(comp) else 2)

    # |S0 ∩ S2|: No (0,0) and no (1,1) => proper 2-coloring required
    # Only possible if graph is bipartite, with 2 choices per component
    c02 = 1 if all(is_bipartite(adj, comp) for comp in components) else 0
    c02 *= 2 ** len(components)

    # |S0 ∩ S1 ∩ S2|: No edges can have any sum => all components must have no edges
    c012 = 1
    for comp in components:
        if has_edges_in_comp(comp):
            c012 = 0
            break
        c012 *= 2

    # Total assignments
    total = 2 ** n

    # Apply inclusion-exclusion
    ans = total - (s0 + s1 + s2) + (c01 + c21 + c02) - c012

    return f"{ans}\n"
