            return parse_expr()

        # Parse a number
        start = pos[0]
        while pos[0] < n and s[pos[0]].isdigit():
            pos[0] += 1
        num = int(s[start:pos[0]])
        d_num = pos[0] - start

        if num == 0:
            return 0, 0

        # Is it a range? n-m
        if pos[0] < n and s[pos[0]] == '-':
            pos[0] += 1
            start2 = pos[0]
            while pos[0] < n and s[pos[0]].isdigit():
                pos[0] += 1
            num2 = int(s[start2:pos[0]])
            return compute_range(num, num2)

        # Is it repetition? n(
        if pos[0] < n and s[pos[0]] == '(':
            pos[0] += 1
            expr_val, expr_digits = parse_expr()
            pos[0] += 1  # skip ')'

            # Concatenate expr_val, num times
            result = expr_val
            for _ in range(num - 1):
                result = concat(result, repr(expr_val, expr_digits))
            return result, expr_digits * num

        return num, d_num

    def parse_term_main():
        val, digits = parse_term()
        if val == 0:
            return parse_expr()
        return val, digits

    return str(parse_expr())
