import math

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, a, b = map(int, lines[0].split())
    arr = list(map(int, lines[1].split()))

    def get_divs(x):
        res = set()
        if x <= 0:
            return res
        for i in range(1, int(math.isqrt(x)) + 1):
            if x % i == 0:
                res.add(i)
                res.add(x // i)
        return res

    cand = set()

    if n > 0:
        for x in [arr[0]-1, arr[0], arr[0]+1]:
            if x > 1: cand.update(get_divs(x))
        if n > 1:
            for x in [arr[-1]-1, arr[-1], arr[-1]+1]:
                if x > 1: cand.update(get_divs(x))

    cand = sorted([d for d in cand if d > 1])

    ans = float('inf')

    if n > 0:
        ans = b * n

    if not cand:
        return str(ans)

    for g in cand:
        # Build prefix cost array (cost to modify elements before index i)
        pre = [0] * (n + 1)
        for i in range(n):
            if arr[i] % g != 0:
                pre[i+1] = pre[i] + b
            else:
                pre[i+1] = pre[i]

        # Build suffix cost array (cost to modify elements from index i onwards)
        suf = [0] * (n + 1)
        for i in range(n - 1, -1, -1):
            if arr[i] % g != 0:
                suf[i] = suf[i+1] + b
            else:
                suf[i] = suf[i+1]

        # Try all subsegments [i, j) to keep
        for i in range(n + 1):
            for j in range(i, n + 1):
                keep_len = j - i
                if keep_len == 0:
                    continue
                cost = pre[i] + suf[j]
                cost += a * (n - keep_len)
                if cost < ans:
                    ans = cost

    return str(ans)
